      primaryDealId,
      callStatus: eng.callStatus || null,
      recordingAvailable: eng.recordingAvailable,
      callDurationMinutes: eng.durationMs ? Math.round(eng.durationMs / 60000) : null,
      engagementKey,
      engagementOwnerId: eng.ownerId ? String(eng.ownerId) : null,
      title: eng.title ? String(eng.title).slice(0, 200) : null,
      meetingDate,
      associations: eng.associations,
      transcriptHash,
      transcriptChars: transcript.length,
      transcriptTruncated,
      piiRedacted: CONFIG.REDACT_PII_BEFORE_AI,
      transcriptForValidation: transcript,
      isSampleTranscript: transcript.includes('[SAMPLE-TRANSCRIPT-PLACEHOLDER]'),
      useLiveAi: USE_LIVE_AI,
      ownerDirectory: OWNER_DIRECTORY,
      aiSystemPrompt: SYSTEM_PROMPT,
      aiUserPrompt: buildUserPrompt({ meetingDate, title: eng.title, engagementType: ev.engagementType, transcript }),
      reason: 'ready_for_ai_extraction',
    });
  }
}

return results;

