// ---------------------------------------------------------------------
// Mode: Run Once for All Items
// Treats the model's answer as untrusted input and maps it onto HubSpot task fields:
//   - parses and schema-validates the JSON
//   - rejects items whose evidence quote is not in the transcript
//   - drops low-confidence and duplicate items
//   - maps assignees only to people in the owner directory
//   - validates and normalises due dates
//   - HTML-escapes every string before it goes into HubSpot
// Emits `action`: create | dry_run_would_create | skip_filtered | skip_no_action_items | error
// =====================================================================

const ENV = (() => { try { return $env || {}; } catch (e) { return {}; } })();
const env = (key, fallback) => {
  const v = ENV[key];
  return v === undefined || v === null || String(v).trim() === '' ? fallback : String(v).trim();
};
const csv = (key, fallback) => env(key, fallback).split(',').map((s) => s.trim().toLowerCase()).filter(Boolean);
const int = (key, fallback) => { const n = parseInt(env(key, String(fallback)), 10); return Number.isFinite(n) ? n : fallback; };
const num = (key, fallback) => { const n = parseFloat(env(key, String(fallback))); return Number.isFinite(n) ? n : fallback; };

const CONFIG = {
  MIN_CONFIDENCE:            Math.min(1, Math.max(0, num('MIN_CONFIDENCE', 0.7))),
  MAX_TASKS_PER_ENGAGEMENT:  Math.min(25, Math.max(1, int('MAX_TASKS_PER_ENGAGEMENT', 10))),
  DEFAULT_DUE_BUSINESS_DAYS: Math.max(0, int('DEFAULT_DUE_BUSINESS_DAYS', 3)),
  DUE_TIME_UTC:              /^\d{2}:\d{2}$/.test(env('DUE_TIME_UTC', '17:00')) ? env('DUE_TIME_UTC', '17:00') : '17:00',
  DEFAULT_TASK_OWNER_ID:     env('DEFAULT_TASK_OWNER_ID', ''),
  UNMATCHED_ASSIGNEE_POLICY: env('UNMATCHED_ASSIGNEE_POLICY', 'engagement_owner').toLowerCase(), // engagement_owner | default_owner | skip
  EXTERNAL_ITEM_POLICY:      env('EXTERNAL_ITEM_POLICY', 'follow_up_task').toLowerCase(),        // follow_up_task | skip
  ASSOCIATE_TO:              csv('ASSOCIATE_TO', 'contacts,companies,deals'),
  MAX_ASSOCIATIONS_PER_TYPE: Math.min(50, Math.max(0, int('MAX_ASSOCIATIONS_PER_TYPE', 10))),
  TASK_SUBJECT_PREFIX:       env('TASK_SUBJECT_PREFIX', ''),
  REMINDER_HOURS_BEFORE:     Math.max(0, int('REMINDER_HOURS_BEFORE', 0)),
  TASK_QUEUE_ID:             /^\d{1,20}$/.test(env('TASK_QUEUE_ID', '')) ? env('TASK_QUEUE_ID', '') : '',
};

// HubSpot-defined association type IDs (task → object)
const ASSOCIATION_TYPE_IDS = { contacts: 204, companies: 192, deals: 216 };
const PRIORITIES = ['HIGH', 'MEDIUM', 'LOW'];
const TASK_TYPES = ['CALL', 'EMAIL', 'TODO'];

// ---------- Helpers ----------
const escapeHtml = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const clean = (s, max) => String(s ?? '').replace(/[\u0000-\u001f\u007f]+/g, ' ').replace(/\s+/g, ' ').trim().slice(0, max);
const norm = (s) => String(s || '').toLowerCase().replace(/[‘’“”]/g, "'").replace(/[^a-z0-9\s]/g, '').replace(/\s+/g, ' ').trim();
function fnv1a(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; } return h.toString(16).padStart(8, '0'); }

function findAiPayload(node, depth = 0) {
  if (node === null || node === undefined || depth > 5) return null;
  if (typeof node === 'string') {
    const s = node.trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
    if (!s.startsWith('{')) return null;
    try { return findAiPayload(JSON.parse(s), depth + 1); } catch (e) { return null; }
  }
  if (Array.isArray(node)) { for (const x of node) { const r = findAiPayload(x, depth + 1); if (r) return r; } return null; }
  if (typeof node === 'object') {
    if (Array.isArray(node.action_items)) return node;
    for (const key of ['message', 'content', 'text', 'output', 'choices', 'response', 'data']) {
      if (key in node) { const r = findAiPayload(node[key], depth + 1); if (r) return r; }
    }
  }
  return null;
}

function validateItem(raw) {
  const errors = [];
  if (!raw || typeof raw !== 'object') return { errors: ['not_an_object'] };
  const title = clean(raw.title, 120);
  const evidence = clean(raw.evidence, 300);
  const confidence = Number(raw.confidence);
  const due = raw.due_date === null || raw.due_date === undefined || raw.due_date === '' ? null : String(raw.due_date).trim();
  if (title.length < 3) errors.push('title_missing');
  if (evidence.length < 5) errors.push('evidence_missing');
  if (!Number.isFinite(confidence) || confidence < 0 || confidence > 1) errors.push('confidence_invalid');
  if (due !== null && !/^\d{4}-\d{2}-\d{2}$/.test(due)) errors.push('due_date_format_invalid');
  return {
    errors,
    item: {
      title, evidence, confidence: Number.isFinite(confidence) ? confidence : 0,
      description: clean(raw.description, 500),
      assigneeName: raw.assignee_name ? clean(raw.assignee_name, 80) : null,
      assigneeType: ['internal', 'external', 'unknown'].includes(raw.assignee_type) ? raw.assignee_type : 'unknown',
      dueDate: errors.includes('due_date_format_invalid') ? null : due,
      dueDateSource: ['explicit', 'relative', 'none'].includes(raw.due_date_source) ? raw.due_date_source : 'none',
      priority: PRIORITIES.includes(String(raw.priority).toUpperCase()) ? String(raw.priority).toUpperCase() : 'MEDIUM',
      taskType: TASK_TYPES.includes(String(raw.task_type).toUpperCase()) ? String(raw.task_type).toUpperCase() : 'TODO',
    },
  };
}

function matchOwner(name, directory) {
  if (!name) return null;
  const n = norm(name);
  const exact = directory.find((o) => norm(o.name) === n || o.aliases.some((a) => norm(a) === n));
  if (exact) return exact;
  const first = n.split(' ')[0];
  const byFirst = directory.filter((o) => norm(o.name).split(' ')[0] === first || o.aliases.some((a) => norm(a) === first));
  return byFirst.length === 1 ? byFirst[0] : null; // ambiguous first names are never guessed
}

function parseDate(s) {
  if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(`${s}T00:00:00Z`);
  return isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s ? null : d;
}
function addBusinessDays(date, n) {
  const d = new Date(date.getTime());
  let added = 0;
  while (added < n) { d.setUTCDate(d.getUTCDate() + 1); const w = d.getUTCDay(); if (w !== 0 && w !== 6) added++; }
  return d;
}
function resolveDue(dueDate, meetingDate) {
  const meeting = parseDate(meetingDate) || parseDate(new Date().toISOString().slice(0, 10));
  const candidate = parseDate(dueDate);
  const latest = new Date(meeting.getTime() + 365 * 86400000);
  let d; let source;
  if (candidate && candidate >= meeting && candidate <= latest) { d = candidate; source = 'ai'; }
  else { d = addBusinessDays(meeting, CONFIG.DEFAULT_DUE_BUSINESS_DAYS); source = candidate ? 'default_ai_date_out_of_range' : 'default_no_date'; }
  const [hh, mm] = CONFIG.DUE_TIME_UTC.split(':').map(Number);
  d.setUTCHours(hh, mm, 0, 0);
  return { iso: d.toISOString(), source };
}

function buildAssociations(assoc, dealLinkMode, primaryDealId) {
  const out = [];
  for (const type of CONFIG.ASSOCIATE_TO) {
    const typeId = ASSOCIATION_TYPE_IDS[type];
    if (!typeId) continue;
    let ids = (assoc && assoc[type]) || [];
    if (type === 'deals') ids = dealLinkMode === 'none' ? [] : dealLinkMode === 'all' ? ids : (primaryDealId ? [primaryDealId] : []);
    for (const id of ids.slice(0, CONFIG.MAX_ASSOCIATIONS_PER_TYPE)) {
      if (!/^[A-Za-z0-9_-]{1,40}$/.test(String(id))) continue;
      out.push({ to: { id: String(id) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: typeId }] });
    }
  }
  return out;
}

// ---------- Main ----------
const staticData = (() => { try { return $getWorkflowStaticData('global'); } catch (e) { return {}; } })();
const inputs = $input.all();
const results = [];

for (let i = 0; i < inputs.length; i++) {
  const ctx = $('Build AI Request').itemMatching(i).json;
  const dryRun = ctx.mode ? ctx.mode.dryRun !== false : true;
  const base = {
    engagementKey: ctx.engagementKey, engagementId: ctx.engagementId, engagementType: ctx.engagementType,
    meetingDate: ctx.meetingDate, transcriptHash: ctx.transcriptHash, mode: ctx.mode, correlationId: ctx.correlationId,
  };
  const emit = (action, extra = {}) => results.push({ json: { ...base, action, ...extra }, pairedItem: { item: i } });

  const payload = findAiPayload(inputs[i].json);
  if (!payload) { emit('error', { reason: 'ai_response_not_valid_json_with_action_items' }); continue; }

  const transcriptNorm = norm(ctx.transcriptForValidation || '');
  const directory = Array.isArray(ctx.ownerDirectory) ? ctx.ownerDirectory : [];
  const summary = clean(payload.summary, 600);
  const accepted = [];
  const seenTitles = new Set();

  for (const raw of payload.action_items.slice(0, 50)) {
    const { errors, item } = validateItem(raw);
    const filtered = (reason) => emit('skip_filtered', { reason, title: item ? item.title : null, assigneeName: item ? item.assigneeName : null, confidence: item ? item.confidence : null });
    if (errors.length) { filtered(`schema_invalid:${errors.join('|')}`); continue; }
    if (item.confidence < CONFIG.MIN_CONFIDENCE) { filtered(`confidence_below_${CONFIG.MIN_CONFIDENCE}`); continue; }
    const ev = norm(item.evidence);
    if (ev.length < 5 || !transcriptNorm.includes(ev)) { filtered('evidence_not_found_in_transcript'); continue; }
    const titleKey = norm(item.title);
    if (seenTitles.has(titleKey)) { filtered('duplicate_item'); continue; }
    seenTitles.add(titleKey);

    // Owner resolution: only owners from the directory are ever assigned.
    const matched = matchOwner(item.assigneeName, directory);
    let ownerId = null; let ownerSource; let subject = item.title;
    if (matched) { ownerId = matched.ownerId; ownerSource = 'matched_directory'; }
    else if (item.assigneeType === 'external') {
      if (CONFIG.EXTERNAL_ITEM_POLICY === 'skip') { filtered('external_assignee_skipped_by_policy'); continue; }
      ownerId = ctx.engagementOwnerId || CONFIG.DEFAULT_TASK_OWNER_ID || null;
      ownerSource = 'external_follow_up';
      subject = `Follow up: ${item.title}${item.assigneeName ? ` (${item.assigneeName})` : ''}`;
    } else {
      if (CONFIG.UNMATCHED_ASSIGNEE_POLICY === 'skip') { filtered('assignee_not_in_owner_directory'); continue; }
      ownerId = CONFIG.UNMATCHED_ASSIGNEE_POLICY === 'default_owner'
        ? (CONFIG.DEFAULT_TASK_OWNER_ID || ctx.engagementOwnerId || null)
        : (ctx.engagementOwnerId || CONFIG.DEFAULT_TASK_OWNER_ID || null);
      ownerSource = 'unmatched_fallback';
    }
    accepted.push({ ...item, ownerId, ownerSource, subject: clean(`${CONFIG.TASK_SUBJECT_PREFIX}${subject}`, 200) });
  }

  if (!accepted.length) {
    if (!dryRun) { staticData.processed = staticData.processed || {}; staticData.processed[ctx.engagementKey] = { hash: ctx.transcriptHash, at: Date.now(), tasks: 0 }; }
    emit('skip_no_action_items', { reason: 'no_items_passed_validation', summary }); continue;
  }

  accepted.forEach((item, idx) => {
    if (idx >= CONFIG.MAX_TASKS_PER_ENGAGEMENT) { emit('skip_filtered', { reason: `over_MAX_TASKS_PER_ENGAGEMENT_${CONFIG.MAX_TASKS_PER_ENGAGEMENT}`, title: item.title }); return; }
    const due = resolveDue(item.dueDate, ctx.meetingDate);
    const idempotencyKey = `${ctx.engagementKey}:${fnv1a(norm(item.title))}`;
    const sourceLabel = 'Call';
    const body = [
      item.description ? `<p>${escapeHtml(item.description)}</p>` : '',
      `<p><strong>Evidence:</strong> “${escapeHtml(item.evidence)}”</p>`,
      `<p><strong>Assignee in transcript:</strong> ${escapeHtml(item.assigneeName || 'not stated')} (${escapeHtml(item.assigneeType)})</p>`,
      `<p><strong>Source:</strong> ${sourceLabel} ${escapeHtml(ctx.engagementId)} · ${escapeHtml(ctx.meetingDate)}${ctx.callDurationMinutes ? ` · ${ctx.callDurationMinutes} min` : ''}${ctx.recordingAvailable ? ' · recording available on the call record' : ''} · AI confidence ${item.confidence.toFixed(2)}</p>`,
      '<p><em>Created automatically by the n8n call action-item assigner (dhRobin Systems). Check it against the call recording before relying on it.</em></p>',
      `<p>Ref: ${escapeHtml(idempotencyKey)}</p>`,
    ].filter(Boolean).join('');
    const properties = {
      hs_task_subject: item.subject,
      hs_task_body: body.slice(0, 5000),
      hs_timestamp: due.iso,
      hs_task_status: 'NOT_STARTED',
      hs_task_priority: item.priority,
      hs_task_type: item.taskType,
    };
    if (item.ownerId) properties.hubspot_owner_id = String(item.ownerId);
    if (CONFIG.TASK_QUEUE_ID) properties.hs_queue_membership_ids = CONFIG.TASK_QUEUE_ID;
    if (CONFIG.REMINDER_HOURS_BEFORE) {
      const reminderMs = new Date(due.iso).getTime() - CONFIG.REMINDER_HOURS_BEFORE * 3600000;
      if (reminderMs > Date.now()) properties.hs_task_reminders = String(reminderMs);
    }
    emit(dryRun ? 'dry_run_would_create' : 'create', {
      reason: item.ownerSource,
      title: item.title,
      assigneeName: item.assigneeName,
      assigneeType: item.assigneeType,
      ownerId: item.ownerId,
      dueAt: due.iso,
      dueSource: due.source,
      priority: item.priority,
      taskType: item.taskType,
      confidence: item.confidence,
      evidence: item.evidence,
      summary,
      idempotencyKey,
      linkedDealId: CONFIG.ASSOCIATE_TO.includes('deals') ? (ctx.dealLinkMode === 'all' ? null : ctx.primaryDealId || null) : null,
      taskPayload: { properties, associations: buildAssociations(ctx.associations, ctx.dealLinkMode, ctx.primaryDealId) },
    });
  });
}

return results;

// Audit Log — compact, secret-free record of each created task; marks the engagement as processed.
// Mode: Run Once for Each Item
const task = $('Validate & Build HubSpot Tasks').item.json;
const res = $json || {};

try {
  const sd = $getWorkflowStaticData('global');
  sd.processed = sd.processed || {};
  sd.processed[task.engagementKey] = { hash: task.transcriptHash, at: Date.now() };
  // Keep the idempotency ledger bounded: drop entries older than 90 days, cap at 5,000.
  const cutoff = Date.now() - 90 * 86400000;
  const entries = Object.entries(sd.processed).filter(([, v]) => v && v.at >= cutoff).sort((a, b) => b[1].at - a[1].at).slice(0, 5000);
  sd.processed = Object.fromEntries(entries);
} catch (e) { /* static data is only persisted for production (active) executions */ }

return {
  json: {
    status: 'task_created',
    hubspotTaskId: res.id || null,
    engagement: task.engagementKey,
    title: task.title,
    ownerId: task.ownerId,
    ownerSource: task.reason,
    dueAt: task.dueAt,
    priority: task.priority,
    taskType: task.taskType,
    linkedDealId: task.linkedDealId || null,
    confidence: task.confidence,
    associationsCount: (task.taskPayload && task.taskPayload.associations || []).length,
    idempotencyKey: task.idempotencyKey,
