// Sanitized Error Handler — shared by the OpenAI node and the HubSpot Task Creator.
// Strips tokens, keys and request internals; never echoes transcript text.
// Mode: Run Once for Each Item
let ctx = {}; let stage = 'unknown';
for (const [node, label] of [['Validate & Build HubSpot Tasks', 'task_creation'], ['Build AI Request', 'ai_extraction']]) {
  try { const j = $(node).item.json; if (j) { ctx = j; stage = label; break; } } catch (e) { /* node not in this item's lineage */ }
}

const err = $json.error || {};
const raw = typeof err === 'string' ? err : (err.message || err.description || 'Upstream request failed');
const message = String(raw)
  .replace(/Bearer\s+[A-Za-z0-9\-_.=]+/gi, 'Bearer [REDACTED]')
  .replace(/pat-[a-z0-9]{2,}-[A-Za-z0-9-]+/gi, '[REDACTED_TOKEN]')
  .replace(/sk-[A-Za-z0-9_-]{10,}/g, '[REDACTED_KEY]')
  .slice(0, 200);
