  task_creation: {
    400: 'HubSpot rejected the task. Check owner IDs, association IDs and the hs_task_* property values.',
    401: 'HubSpot token invalid or expired. Rotate HUBSPOT_ACCESS_TOKEN.',
    403: 'HubSpot token is missing a scope required to create tasks or read the associated records. Compare the private app scopes with the HubSpot API reference.',
    404: 'An associated record no longer exists.',
    429: 'HubSpot rate limit hit. Reduce concurrency.',
  },
  ai_extraction: {
    400: 'OpenAI rejected the request. Check the model name and that it supports JSON output.',
    401: 'OpenAI key invalid. Update the OpenAI credential in n8n.',
    429: 'OpenAI rate limit or quota reached. Check usage limits and billing.',
  },
};

return {
  json: {
    status: stage === 'task_creation' ? 'task_creation_failed' : 'ai_extraction_failed',
    stage,
    engagement: ctx.engagementKey || null,
    title: ctx.title || null,
    httpStatus,
    message,
    hint: (HINTS[stage] && HINTS[stage][httpStatus]) || 'Check the n8n execution log and the upstream API status page.',
    correlationId: ctx.correlationId || null,
    loggedAt: new Date().toISOString(),
  },
};
